import Mathlib.CategoryTheory.Limits.Shapes.BinaryCoproducts
import Mathlib.CategoryTheory.Group
import Mathlib.CategoryTheory.Limits.Preserves.Basic

open CategoryTheory Limits

universe u

variable {G H : GrpCat.{u}}

theorem freeProdGrp_iso_coprod [HasBinaryCoproduct G H] :
    Nonempty (GrpCat.of (Monoid.Coprod G H) ≅ coprod G H) := by
  -- Use the universal property of the free product to construct the isomorphism
  letI := Monoid.Coprod.instGroup
  letI := Monoid.CoprodI.instGroup
  letI := AddCommGrpCat.instHasBinaryBiproducts

  -- Construct the isomorphism
  let iso := {
    hom := {
      app := fun K => {
        toFun := fun f => Monoid.Coprod.lift (fun i => f i),
        map_one' := by simp,
        map_mul' := fun x y => by simp
      },
      naturality' := fun K L f g => by simp
    },
    inv := {
      app := fun K => {
        toFun := fun f => Monoid.CoprodI.lift (fun i => f i),
        map_one' := by simp,
        map_mul' := fun x y => by simp
      },
      naturality' := fun K L f g => by simp
    }
  }

  -- Verify the isomorphism
  have hom_inv_id : iso.hom ≫ iso.inv = 𝟙 _ := by ext; simp
  have inv_hom_id : iso.inv ≫ iso.hom = 𝟙 _ := by ext; simp

  exact ⟨iso⟩"}
